/**
 * Private (secret) status pages: a page at /p/<token> that shows a chosen set
 * of services, also ones hidden from the main status page, to whoever has the
 * link. Not indexed, never cached, no analytics (see isPersonalPath).
 *
 * The token is generated by the server (160 random bits, lower-case base32) and
 * stored only as its SHA-256 hash. Base32 is case-insensitive: a link retyped
 * or rewritten in upper case still works (see normalizePrivatePageToken). It is shown once, in the answer that created or regenerated it.
 */
import { z } from 'zod';
import type { OverallStatus, ServiceStatus } from './status.js';
import type { PublicIncident, PublicMaintenance, PublicService } from './schemas.js';
import { zId, zTimestamp } from './schemas.js';

/** Path prefix of the private pages: /p/<token>. */
export const PRIVATE_PAGE_PREFIX = '/p';

/** HTTP header that carries the token to the private page API (never the URL of an API request). */
export const PRIVATE_PAGE_TOKEN_HEADER = 'x-private-page-token';

/** Requests per minute and client to private pages (API and HTML), against guessing tokens. */
export const PRIVATE_PAGE_REQUESTS_PER_MINUTE = 60;

/** Shape of a token:32 characters of lower-case base32 (160 bits). */
export const PRIVATE_PAGE_TOKEN_PATTERN = /^[a-z2-7]{32}$/;

/** Whether `value` looks like a private page token (anything else is "not found" without asking the database). */
export function isPrivatePageToken(value: string): boolean {
  return PRIVATE_PAGE_TOKEN_PATTERN.test(value);
}

/**
 * The token of a link as the server knows it: lower case (base32 is
 * case-insensitive, so /p/<TOKEN> is the same page). Every entry point (page
 * path, API header, server-side source) passes the token through this first.
 */
export function normalizePrivatePageToken(value: string): string {
  return value.toLowerCase();
}

/** Link base of a private page (no trailing slash): `/p/<token>`. */
export function privatePageBase(token: string): string {
  return `${PRIVATE_PAGE_PREFIX}/${encodeURIComponent(token)}`;
}

/** Input of the admin API (create and full update). */
export const PrivatePageInput = z.object({
  name: z.string().trim().min(1).max(120),
  description: z.string().max(2000).nullish(),
  /** Services shown on the page, in this order; any service, also hidden ones. */
  serviceIds: z.array(zId).max(500).default([]),
  /** The link stops working at this time; null: never. */
  expiresAt: zTimestamp.nullish(),
  enabled: z.boolean().default(true),
});
export type PrivatePageInput = z.infer<typeof PrivatePageInput>;

/** A private page in the admin API (`private-pages`). The token itself is never stored. */
export interface AdminPrivatePage {
  id: string;
  name: string;
  description: string | null;
  serviceIds: string[];
  expiresAt: string | null;
  enabled: boolean;
  /** expiresAt lies in the past. */
  expired: boolean;
  createdAt: string;
  updatedAt: string;
  /** When the current link was created (creation or the last regeneration). */
  tokenCreatedAt: string;
  /** Only in the answer that created or regenerated the link. */
  token?: string;
  /** The full link (PUBLIC_BASE_URL + /p/<token>), only together with `token`. */
  url?: string;
}

/**
 * A private page as its visitors see it (GET /api/public/private-page,
 * resource type `private-pages`): name and description, the overall status of
 * its services, the services with their uptime bars, and the public incidents
 * and maintenance windows that affect them.
 */
export interface PublicPrivatePage {
  id: string;
  name: string;
  description: string | null;
  overall: OverallStatus;
  counts: Record<ServiceStatus, number>;
  generatedAt: string;
  services: PublicService[];
  activeIncidents: PublicIncident[];
  activeMaintenances: PublicMaintenance[];
  upcomingMaintenances: PublicMaintenance[];
}
